import{o as e,c as r,a2 as t}from"./chunks/framework.DpbdyYUv.js";const o="/unit_devlab_esp32_examples/assets/AditionalBoardsManagerURL.B7czEuFr.png",i="/unit_devlab_esp32_examples/assets/BoardsManager.gybYRE1E.png",s="/unit_devlab_esp32_examples/assets/boards-esp32c6.xm1yD14t.png",p=JSON.parse('{"title":"Configuración de Arduino IDE para PULSAR C6","description":"","frontmatter":{},"headers":[],"relativePath":"pulsar-c6-getting-started/02_0_duino.md","filePath":"pulsar-c6-getting-started/02_0_duino.md"}'),n={name:"pulsar-c6-getting-started/02_0_duino.md"},u=Object.assign(n,{setup(c){return(l,a)=>(e(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="configuracion-de-arduino-ide-para-pulsar-c6" tabindex="-1">Configuración de Arduino IDE para PULSAR C6 <a class="header-anchor" href="#configuracion-de-arduino-ide-para-pulsar-c6" aria-label="Permalink to &quot;Configuración de Arduino IDE para PULSAR C6&quot;">​</a></h1><p>Arduino IDE es un entorno independiente de MicroPython y el flujo de trabajo recomendado para las prácticas y ejemplos de la placa PULSAR C6 (ESP32-C6). Esta página explica cómo instalarlo, configurar la placa y cargar un programa.</p><h2 id="_1-instalar-arduino-ide" tabindex="-1">1. Instalar Arduino IDE <a class="header-anchor" href="#_1-instalar-arduino-ide" aria-label="Permalink to &quot;1. Instalar Arduino IDE&quot;">​</a></h2><p>Descarga e instala Arduino IDE 2.x desde el <a href="https://www.arduino.cc/en/software" target="_blank">sitio web oficial de Arduino</a>.</p><h2 id="_2-agregar-la-url-del-gestor-de-placas-para-pulsar-c6" tabindex="-1">2. Agregar la URL del gestor de placas para PULSAR C6 <a class="header-anchor" href="#_2-agregar-la-url-del-gestor-de-placas-para-pulsar-c6" aria-label="Permalink to &quot;2. Agregar la URL del gestor de placas para PULSAR C6&quot;">​</a></h2><p>Arduino permite instalar paquetes de plataformas de terceros mediante el <strong>Gestor de placas</strong>. Para que Arduino IDE reconozca la PULSAR C6, primero debes agregar el índice del paquete ESP32 de UNIT Electronics.</p><ol><li>Abre Arduino IDE y ve a <strong>Archivo &gt; Preferencias</strong>.</li></ol><figure><p><img src="'+o+'" class="align-center" style="width:100.0%;" alt="Campo de URLs adicionales del gestor de placas"></p><figcaption>Referencia para localizar el campo de URLs adicionales</figcaption></figure><ol start="2"><li>En el campo <strong>Gestor de URLs Adicionales de Tarjetas</strong>, pega exactamente la siguiente URL:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/UNIT-Electronics/Uelectronics-ESP32-Arduino-Package/main/package_Uelectronics_esp32_index.json</span></span></code></pre></div><ol start="3"><li>Presiona <strong>OK</strong> para cerrar el cuadro de diálogo.</li></ol><h2 id="_3-instalar-el-paquete-esp32-desde-el-gestor-de-placas" tabindex="-1">3. Instalar el paquete ESP32 desde el Gestor de placas <a class="header-anchor" href="#_3-instalar-el-paquete-esp32-desde-el-gestor-de-placas" aria-label="Permalink to &quot;3. Instalar el paquete ESP32 desde el Gestor de placas&quot;">​</a></h2><ol><li>Ve a <strong>Herramientas &gt; Placa &gt; Gestor de placas</strong>.</li><li>Escribe <code>UNIT Electronics ESP32</code> en el buscador e instala el paquete <strong>UNIT Electronics ESP32</strong>.</li></ol><figure><img src="'+i+'" class="align-center" style="width:50.0%;" alt="Gestor de placas con el paquete ESP32"><figcaption>Referencia visual del Gestor de placas</figcaption></figure><ol start="3"><li>Una vez instalado, ve a <strong>Herramientas &gt; Placa &gt; UNIT Electronics ESP32</strong> y selecciona <strong>PULSAR ESP32-C6</strong>.</li></ol><figure><img src="'+s+'" class="align-center" style="width:150.0%;" alt="Gestor de placas con el paquete ESP32"><figcaption>Referencia visual del Gestor de placas</figcaption></figure><p>Verifica que el puerto serie correcto esté seleccionado en <strong>Herramientas &gt; Puerto</strong> antes de compilar y cargar un sketch.</p><h2 id="_4-compilar-y-cargar-un-programa" tabindex="-1">4. Compilar y cargar un programa <a class="header-anchor" href="#_4-compilar-y-cargar-un-programa" aria-label="Permalink to &quot;4. Compilar y cargar un programa&quot;">​</a></h2><ol><li>Conecta la PULSAR C6 mediante un cable USB que permita transferencia de datos.</li><li>Abre el sketch que deseas cargar.</li><li>Confirma que estén seleccionados <strong>PULSAR ESP32-C6</strong> y el puerto serie de la placa.</li><li>Presiona <strong>Verificar</strong> para compilar el programa.</li><li>Presiona <strong>Cargar</strong> y espera el mensaje de finalización.</li></ol><p>Si el puerto no aparece, prueba otro cable USB o puerto de la computadora y vuelve a abrir Arduino IDE.</p><h2 id="paquetes-adicionales-de-unit-electronics" tabindex="-1">Paquetes adicionales de UNIT Electronics <a class="header-anchor" href="#paquetes-adicionales-de-unit-electronics" aria-label="Permalink to &quot;Paquetes adicionales de UNIT Electronics&quot;">​</a></h2><p>Los siguientes índices no son necesarios para programar la PULSAR C6, pero puedes agregarlos para dejar Arduino IDE preparado para otras familias de placas de UNIT Electronics.</p><table tabindex="0"><thead><tr><th>Familia</th><th>Repositorio</th></tr></thead><tbody><tr><td>ESP32</td><td><a href="https://github.com/UNIT-Electronics/Uelectronics-ESP32-Arduino-Package" target="_blank" rel="noreferrer">Uelectronics-ESP32-Arduino-Package</a></td></tr><tr><td>RP2040</td><td><a href="https://github.com/UNIT-Electronics/Uelectronics-RP2040-Arduino-Package" target="_blank" rel="noreferrer">Uelectronics-RP2040-Arduino-Package</a></td></tr><tr><td>CH552 / MCS51</td><td><a href="https://github.com/UNIT-Electronics/Uelectronics-CH552-Arduino-Package" target="_blank" rel="noreferrer">Uelectronics-CH552-Arduino-Package</a></td></tr><tr><td>PY32</td><td><a href="https://github.com/UNIT-Electronics-MX/unit_electronics_py32_arduino_package" target="_blank" rel="noreferrer">unit_electronics_py32_arduino_package</a></td></tr><tr><td>ATtiny</td><td><a href="https://github.com/UNIT-Electronics-MX/uelectronics_attinycore_arduino_package" target="_blank" rel="noreferrer">uelectronics_attinycore_arduino_package</a></td></tr></tbody></table><h3 id="copiar-todos-los-indices" tabindex="-1">Copiar todos los índices <a class="header-anchor" href="#copiar-todos-los-indices" aria-label="Permalink to &quot;Copiar todos los índices&quot;">​</a></h3><p>Arduino IDE acepta varias URLs separadas por comas. Copia la línea completa y pégala en <strong>Gestor de URLs Adicionales de Tarjetas</strong> para registrar todos los paquetes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/UNIT-Electronics/Uelectronics-ESP32-Arduino-Package/main/package_Uelectronics_esp32_index.json,https://raw.githubusercontent.com/UNIT-Electronics/Uelectronics-RP2040-Arduino-Package/main/package_Uelectronics_rp2040_index.json,https://raw.githubusercontent.com/UNIT-Electronics/Uelectronics-CH552-Arduino-Package/refs/heads/main/package_duino_mcs51_index.json,https://raw.githubusercontent.com/UNIT-Electronics-MX/unit_electronics_py32_arduino_package/main/package_unit_electronics_py32_index.json,https://raw.githubusercontent.com/UNIT-Electronics-MX/uelectronics_attinycore_arduino_package/refs/heads/main/package_uelectronics_attiny_custom.json</span></span></code></pre></div><p>Agregar los índices solo permite que los paquetes aparezcan en el Gestor de placas; no instala automáticamente todos los paquetes. Instala únicamente los que vayas a utilizar.</p><h2 id="documentacion-adicional" tabindex="-1">Documentación adicional <a class="header-anchor" href="#documentacion-adicional" aria-label="Permalink to &quot;Documentación adicional&quot;">​</a></h2><p>Consulta la <a href="https://wiki.uelectronics.com/tutoriales/inicio-arduino" target="_blank">guía de instalación de paquetes de UNIT Electronics</a> para más detalle y capturas de pantalla por sistema operativo.</p>',29)])]))}});export{p as __pageData,u as default};
